<?php require __DIR__.'/bootstrap.php'; $ref=trim((string)($_GET['reference']??$_POST['reference']??''));$order=null;if($ref!==''){foreach(read_json('orders.json',[]) as $o)if(strtoupper($o['reference']??'')===strtoupper($ref)){$order=$o;break;}}site_header('Track your order'); ?>
<section class="page-hero"><div class="eyebrow">Order tracking</div><h1>Follow your order.</h1><p>Enter your order reference to see the latest payment and fulfilment status.</p></section><section class="content"><form class="card-panel" method="post" style="max-width:600px;margin:0 auto 35px"><div class="field"><label for="reference">Order reference *</label><input id="reference" name="reference" required placeholder="e.g. BB-A1B2C3D4E5" value="<?= e($ref) ?>"></div><button class="button" type="submit">Find my order ↗</button><p class="muted">Keep your order reference private. Anyone who has it may be able to view limited order information.</p></form><?php if($ref&&!$order): ?><div class="alert error">We couldn't find an order with that reference. Check it and try again.</div><?php endif; ?><?php if($order): ?><div class="card-panel"><div class="eyebrow">Order <?= e($order['reference']) ?></div><h2><?= e($order['status']) ?></h2><p>Payment: <span class="status <?= e($order['payment_status']) ?>"><?= e(ucfirst($order['payment_status'])) ?></span> · Placed <?= e(date('j M Y, g:i a',strtotime($order['created_at']))) ?></p><div class="timeline"><?php foreach(($order['timeline']??[['status'=>$order['status'],'at'=>$order['created_at']]]) as $t): ?><div class="timeline-item active"><strong><?= e($t['status']) ?></strong><small><?= e(date('j M Y, g:i a',strtotime($t['at']))) ?></small></div><?php endforeach; ?></div><h3>Order summary</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Cake</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($order['items'] as $i): ?><tr><td><?= e($i['name']) ?><br><small><?= e($i['size']) ?> · <?= e($i['flavour']) ?></small><br><small>Custom message: <?= e($i['custom_message']) ?></small></td><td><?= (int)$i['qty'] ?></td><td><?= money((float)$i['line_total']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="summary-row"><span>Subtotal</span><strong><?= money((float)$order['subtotal']) ?></strong></div><div class="summary-row"><span>Delivery</span><strong><?= money((float)$order['delivery_fee']) ?></strong></div><div class="summary-row total"><span>Total</span><strong><?= money((float)$order['total']) ?></strong></div><p><strong><?= $order['fulfilment']==='delivery'?'Delivery':'Pickup' ?>:</strong> <?= e($order['scheduled_at']) ?></p><p><?= $order['fulfilment']==='delivery'?e($order['delivery']['address']??'').' · '.e($order['delivery']['area']??''):e(cfg('address')) ?></p><button class="button button-outline" onclick="window.print()">Print receipt / Save PDF</button></div><?php endif; ?></section><?php site_footer(); ?>
